using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalFlagsPortrait{
static FinalFlagsPortrait(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalFlagsPortrait.request")||EditorApplication.isCompiling)return;File.Delete("FinalFlagsPortrait.request");Run();}
static void Run(){try{string dir="Assets/Scenes/Oasis/CityBuildingFlags";var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");string backup="FinalEnvironmentRoadBackup/FlagsBeforePortrait-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);var type=typeof(FinalCityBuildingFlags).GetNestedType("Buffer",BindingFlags.NonPublic);string[] nations={"USA","China","England","Qatar"};for(int i=0;i<4;i++){string path=dir+"/"+nations[i]+" Flag.asset";File.Copy(path,backup+"/"+nations[i]+".asset");var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);var buffer=Activator.CreateInstance(type,true);var mesh=(Mesh)type.GetMethod("Flag").Invoke(buffer,new object[]{i});if(mesh.triangles.Length!=old.triangles.Length)throw new Exception("Triangle budget changed");old.Clear();old.vertices=mesh.vertices;old.normals=mesh.normals;old.uv=mesh.uv;old.colors=mesh.colors;old.triangles=mesh.triangles;old.bounds=mesh.bounds;old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);}
var root=scene.GetRootGameObjects().Single(g=>g.name=="City Building Flags - 20 Buildings");foreach(var lod in root.GetComponentsInChildren<LODGroup>()){lod.RecalculateBounds();lod.size=Mathf.Max(8,lod.size);}PrefabUtility.SaveAsPrefabAssetAndConnect(root,dir+"/City Building Flags.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/FlagsPortraitReport.txt","SUCCESS: 80 portrait flags, 20 buildings; rotated atlas UVs; poles and mounts preserved; 4 shared meshes; unchanged triangle budget; wind and LODs retained; saved scene and prefab.");File.WriteAllText("FinalBuildingFlagsFinish.request","run");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/FlagsPortraitReport.txt","FAILED "+e);Debug.LogException(e);}}}
